//! The abstract test items of IEC 61850-10, as a coverage table.
//!
//! Each row is one item: its identifier, the clause and table it appears in,
//! and the check it prescribes. The table is a reference list rather than a set
//! of tests. An item counts as implemented when a test function named after it
//! exists in the `s_srv` module of this binary; most items have none.
//!
//! The two meta-tests in `main.rs` keep the table usable: the row count matches
//! `TOTAL_ITEMS`, and no description is blank.

#![allow(dead_code)]

pub const TOTAL_ITEMS: usize = 607;

